#!/bin/sh
# Prove real unchecked errors fail beside explicitly accepted buffer writes.
set -eu
root=$(pwd)
fixture=$(mktemp -d)
trap 'rm -rf "$fixture"' EXIT HUP INT TERM
printf '%s\n' 'module errcheck-fixture' 'go 1.27.0' > "$fixture/go.mod"
cat > "$fixture/accepted.go" <<'GO'
package fixture
import "bytes"
func accepted() { var buffer bytes.Buffer; buffer.WriteString("cannot fail") }
GO
cat > "$fixture/generated.go" <<'GO'
// Code generated by the errcheck smoke fixture. DO NOT EDIT.
package fixture
import "os"
func generated() { os.Chdir("not executed") }
GO
cd "$fixture"
for kind in statement blank test; do
    file=fixture.go
    call='os.Chdir("not executed")'
    if [ "$kind" = blank ]; then call='_ = os.Chdir("not executed")'; fi
    if [ "$kind" = test ]; then file=fixture_test.go; fi
    printf 'package fixture\nimport "os"\nfunc rejected() { %s }\n' "$call" > "$file"
    if "$@" -blank -excludeonly -exclude "$root/scripts/errcheck-excludes.txt" -ignoregenerated ./... > output 2>&1; then
        cat output
        echo "errcheck accepted $kind error" >&2
        exit 1
    fi
    cat output
    # Download/load/tool errors do not count as detecting the fixture.
    grep -E "$file:[0-9]+:[0-9]+:.*os.Chdir" output
    rm "$file"
done
"$@" -blank -excludeonly -exclude "$root/scripts/errcheck-excludes.txt" -ignoregenerated ./...
